def count_matching(xs, predicate_name):  
    count = 0  
    for x in xs:  
        if predicate_name == 'positive' and x > 0:  
            count += 1  
        elif predicate_name == 'negative' and x < 0:  
            count += 1  
        elif predicate_name == 'even' and x % 2 == 0:  
            count += 1  
        elif predicate_name == 'odd' and x % 2 != 0:  
            count += 1  
    return count

def max_list(xs):
    if len(xs) == 0:
        return None
    return max(xs)

def reverse_string(s):
    result = ''
    for i in range(len(s) - 1, -1, -1):
        result += s[i]
    return result
